"""dialogues between the 6 roster characters (183 clips). Written by the voice director (content), source AssetGen/audio/script/wave_*.txt -> voice_script.json; voice = char_id (VOIX_ARCHITECTURE.md principle 2). Never edit: new content goes to a new batch."""
ITEMS = [
    {'cat': 'dialogue', 'text': 'Vasilescu, vous étiez à Austerlitz ? On dirait que vous y étiez.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0151_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0151', 'turn': 1, 'speaker': 'A', 'context': 'austerlitz'},
    {'cat': 'dialogue', 'text': "J'y ai croisé un petit Corse très agité. Il ne tenait pas en place.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0151_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0151', 'turn': 2, 'speaker': 'B', 'context': 'austerlitz'},
    {'cat': 'dialogue', 'text': 'Napoléon ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0151_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0151', 'turn': 3, 'speaker': 'A', 'context': 'austerlitz'},
    {'cat': 'dialogue', 'text': "C'est possible. Il ne m'a pas laissé sa carte.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0151_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0151', 'turn': 4, 'speaker': 'B', 'context': 'austerlitz'},
    {'cat': 'dialogue', 'text': 'Colonel, que pensez-vous des chauves-souris ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0152_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0152', 'turn': 1, 'speaker': 'A', 'context': 'bats'},
    {'cat': 'dialogue', 'text': 'Des rats avec des ailes. On les tirait au fusil, à la caserne.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0152_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0152', 'turn': 2, 'speaker': 'B', 'context': 'bats'},
    {'cat': 'dialogue', 'text': 'Je vous demanderai de ne pas répéter ça devant ma famille.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0152_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0152', 'turn': 3, 'speaker': 'A', 'context': 'bats'},
    {'cat': 'dialogue', 'text': 'Votre poignée de main est glacée, comte !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0153_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0153', 'turn': 1, 'speaker': 'A', 'context': 'cold hand'},
    {'cat': 'dialogue', 'text': 'Je viens du jardin, colonel. La nuit est fraîche.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0153_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0153', 'turn': 2, 'speaker': 'B', 'context': 'cold hand'},
    {'cat': 'dialogue', 'text': "Vous n'êtes pas sorti de la soirée.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0153_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0153', 'turn': 3, 'speaker': 'A', 'context': 'cold hand'},
    {'cat': 'dialogue', 'text': "Alors c'est le jardin qui est venu à moi.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0153_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0153', 'turn': 4, 'speaker': 'B', 'context': 'cold hand'},
    {'cat': 'dialogue', 'text': 'Je vous envie votre moustache, colonel. Elle a du caractère.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0154_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0154', 'turn': 1, 'speaker': 'A', 'context': 'moustaches'},
    {'cat': 'dialogue', 'text': 'Vingt ans de cire, monsieur ! Et la vôtre ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0154_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0154', 'turn': 2, 'speaker': 'B', 'context': 'moustaches'},
    {'cat': 'dialogue', 'text': 'La mienne a quatre siècles. Elle ne pousse plus, elle se souvient.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0154_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0154', 'turn': 3, 'speaker': 'A', 'context': 'moustaches'},
    {'cat': 'dialogue', 'text': "Colonel, vous m'emmènerez faire du cheval, un jour ?", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0155_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0155', 'turn': 1, 'speaker': 'A', 'context': 'riding'},
    {'cat': 'dialogue', 'text': 'Volontiers, mademoiselle. Vous montez en amazone ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0155_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0155', 'turn': 2, 'speaker': 'B', 'context': 'riding'},
    {'cat': 'dialogue', 'text': "Je monte comme je danse : très mal, mais avec beaucoup d'allure.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0155_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0155', 'turn': 3, 'speaker': 'A', 'context': 'riding'},
    {'cat': 'dialogue', 'text': 'Mademoiselle, vous avez vu passer mon épouse ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0156_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0156', 'turn': 1, 'speaker': 'A', 'context': 'wife smoking'},
    {'cat': 'dialogue', 'text': 'Elle est au fumoir, colonel. Avec un cigare.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0156_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0156', 'turn': 2, 'speaker': 'B', 'context': 'wife smoking'},
    {'cat': 'dialogue', 'text': 'Ma femme ne fume pas !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0156_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0156', 'turn': 3, 'speaker': 'A', 'context': 'wife smoking'},
    {'cat': 'dialogue', 'text': 'Ce soir, elle découvre beaucoup de choses.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0156_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0156', 'turn': 4, 'speaker': 'B', 'context': 'wife smoking'},
    {'cat': 'dialogue', 'text': 'Colonel, entre nous, qui a le plus de dettes dans ce salon ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0157_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0157', 'turn': 1, 'speaker': 'A', 'context': 'debts gossip'},
    {'cat': 'dialogue', 'text': "Le jeune homme en queue-de-pie. Il m'a déjà tapé deux fois.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0157_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0157', 'turn': 2, 'speaker': 'B', 'context': 'debts gossip'},
    {'cat': 'dialogue', 'text': 'Seulement deux ? Il vous apprécie.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0157_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0157', 'turn': 3, 'speaker': 'A', 'context': 'debts gossip'},
    {'cat': 'dialogue', 'text': 'De mon temps, les femmes ne parlaient pas de politique.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0158_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0158', 'turn': 1, 'speaker': 'A', 'context': 'politics'},
    {'cat': 'dialogue', 'text': "De votre temps, colonel, elles n'avaient pas le droit d'en parler.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0158_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0158', 'turn': 2, 'speaker': 'B', 'context': 'politics'},
    {'cat': 'dialogue', 'text': "Et c'était très reposant.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0158_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0158', 'turn': 3, 'speaker': 'A', 'context': 'politics'},
    {'cat': 'dialogue', 'text': 'Pour vous.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0158_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0158', 'turn': 4, 'speaker': 'B', 'context': 'politics'},
    {'cat': 'dialogue', 'text': 'Colonel, vous avez une tête à cacher un excellent cognac quelque part.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0159_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0159', 'turn': 1, 'speaker': 'A', 'context': 'boot'},
    {'cat': 'dialogue', 'text': 'Dans ma botte gauche, jeune homme. Et il y reste.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0159_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0159', 'turn': 2, 'speaker': 'B', 'context': 'boot'},
    {'cat': 'dialogue', 'text': 'Jeune homme, vous savez au moins tenir un sabre ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0160_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0160', 'turn': 1, 'speaker': 'A', 'context': 'sabre'},
    {'cat': 'dialogue', 'text': "Je sais tenir une coupe, colonel. C'est plus léger, et ça blesse moins.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0160_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0160', 'turn': 2, 'speaker': 'B', 'context': 'sabre'},
    {'cat': 'dialogue', 'text': 'Colonel, on dit que vous avez sauvé un général, en seize.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0161_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0161', 'turn': 1, 'speaker': 'A', 'context': 'general'},
    {'cat': 'dialogue', 'text': "C'est exact. Je l'ai porté sur mon dos pendant trois kilomètres.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0161_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0161', 'turn': 2, 'speaker': 'B', 'context': 'general'},
    {'cat': 'dialogue', 'text': 'Quelle bravoure !', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0161_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0161', 'turn': 3, 'speaker': 'A', 'context': 'general'},
    {'cat': 'dialogue', 'text': 'Il dormait. Il avait trop bu au mess.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0161_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0161', 'turn': 4, 'speaker': 'B', 'context': 'general'},
    {'cat': 'dialogue', 'text': 'Vous avez vu ces types en imperméable ? Ils vous regardent.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0162_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0162', 'turn': 1, 'speaker': 'A', 'context': 'siege'},
    {'cat': 'dialogue', 'text': "Ce sont peut-être mes créanciers, colonel. Ils s'habillent tous pareil.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0162_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0162', 'turn': 2, 'speaker': 'B', 'context': 'siege'},
    {'cat': 'dialogue', 'text': "Alors cachez-vous derrière moi. J'ai l'habitude des sièges.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0162_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0162', 'turn': 3, 'speaker': 'A', 'context': 'siege'},
    {'cat': 'dialogue', 'text': 'Colonel, à quelle heure avez-vous quitté le fumoir ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0163_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0163', 'turn': 1, 'speaker': 'A', 'context': 'smoking room clock'},
    {'cat': 'dialogue', 'text': "À onze heures pile. Un militaire est toujours à l'heure.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0163_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0163', 'turn': 2, 'speaker': 'B', 'context': 'smoking room clock'},
    {'cat': 'dialogue', 'text': "L'horloge du fumoir retarde de vingt minutes.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0163_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0163', 'turn': 3, 'speaker': 'A', 'context': 'smoking room clock'},
    {'cat': 'dialogue', 'text': 'Alors cette horloge est une civile.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0163_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0163', 'turn': 4, 'speaker': 'B', 'context': 'smoking room clock'},
    {'cat': 'dialogue', 'text': 'Vous ne buvez rien, vous ? Pas même un cognac ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0164_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0164', 'turn': 1, 'speaker': 'A', 'context': 'watch with cognac'},
    {'cat': 'dialogue', 'text': 'Je veille, colonel.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0164_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0164', 'turn': 2, 'speaker': 'B', 'context': 'watch with cognac'},
    {'cat': 'dialogue', 'text': "On peut veiller avec un cognac. J'ai fait toute la guerre comme ça.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0164_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0164', 'turn': 3, 'speaker': 'A', 'context': 'watch with cognac'},
    {'cat': 'dialogue', 'text': 'Vous avez entendu un cri, vers minuit moins le quart ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0165_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0165', 'turn': 1, 'speaker': 'A', 'context': 'scream'},
    {'cat': 'dialogue', 'text': "J'ai entendu ma femme. C'est souvent la même chose.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0165_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0165', 'turn': 2, 'speaker': 'B', 'context': 'scream'},
    {'cat': 'dialogue', 'text': 'Si vous êtes un justicier, arrêtez-moi celui qui a mis du jazz partout !', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0166_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0166', 'turn': 1, 'speaker': 'A', 'context': 'jazz crime'},
    {'cat': 'dialogue', 'text': 'Certains crimes dépassent mes compétences, colonel.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0166_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0166', 'turn': 2, 'speaker': 'B', 'context': 'jazz crime'},
    {'cat': 'dialogue', 'text': 'Mon colonel, tu me racontes une histoire de guerre ? Une courte.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0167_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0167', 'turn': 1, 'speaker': 'A', 'context': 'short story'},
    {'cat': 'dialogue', 'text': 'Seize. La boue. Le froid. Fin.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0167_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0167', 'turn': 2, 'speaker': 'B', 'context': 'short story'},
    {'cat': 'dialogue', 'text': "C'est ma préférée.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0167_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0167', 'turn': 3, 'speaker': 'A', 'context': 'short story'},
    {'cat': 'dialogue', 'text': "Mademoiselle, ce fourreau argenté, ce n'est pas un peu court ?", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0168_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0168', 'turn': 1, 'speaker': 'A', 'context': 'short dress'},
    {'cat': 'dialogue', 'text': "C'est pour mieux danser, mon colonel. Toi, t'as bien des bottes jusqu'aux genoux.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0168_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0168', 'turn': 2, 'speaker': 'B', 'context': 'short dress'},
    {'cat': 'dialogue', 'text': "Le comte m'a dit que j'avais un cou appétissant. C'est un compliment, ça ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0169_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0169', 'turn': 1, 'speaker': 'A', 'context': 'appetizing'},
    {'cat': 'dialogue', 'text': "Venant d'un Roumain, je n'en jurerais pas. Restez près de moi.", 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0169_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0169', 'turn': 2, 'speaker': 'B', 'context': 'appetizing'},
    {'cat': 'dialogue', 'text': 'Vous chanterez « La Madelon », ce soir ?', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0170_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0170', 'turn': 1, 'speaker': 'A', 'context': 'madelon duet'},
    {'cat': 'dialogue', 'text': 'Si tu la chantes avec moi, mon colonel. Devant tout le monde.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0170_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0170', 'turn': 2, 'speaker': 'B', 'context': 'madelon duet'},
    {'cat': 'dialogue', 'text': 'Devant tout le monde ? Bon. Mais je reste au garde-à-vous.', 'voice': 'char_colonel', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0170_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0170', 'turn': 3, 'speaker': 'A', 'context': 'madelon duet'},
    {'cat': 'dialogue', 'text': 'Mademoiselle Sandra, accepteriez-vous de visiter mon château, dans les Carpates ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0171_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0171', 'turn': 1, 'speaker': 'A', 'context': 'carpathians'},
    {'cat': 'dialogue', 'text': 'Il y a des bals, là-bas ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0171_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0171', 'turn': 2, 'speaker': 'B', 'context': 'carpathians'},
    {'cat': 'dialogue', 'text': 'Un seul. Il dure depuis trois cents ans.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0171_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0171', 'turn': 3, 'speaker': 'A', 'context': 'carpathians'},
    {'cat': 'dialogue', 'text': 'Comte, vous ne vieillissez pas. Quel est votre secret ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0172_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0172', 'turn': 1, 'speaker': 'A', 'context': 'no wrinkles'},
    {'cat': 'dialogue', 'text': 'Le repos, très chère. Le jour, je ne fais rien du tout.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0172_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0172', 'turn': 2, 'speaker': 'B', 'context': 'no wrinkles'},
    {'cat': 'dialogue', 'text': "Moi non plus, et pourtant j'ai une ride.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0172_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0172', 'turn': 3, 'speaker': 'A', 'context': 'no wrinkles'},
    {'cat': 'dialogue', 'text': 'On dit que vous avez trois fiancés dans ce salon.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0173_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0173', 'turn': 1, 'speaker': 'A', 'context': 'fifth fiance'},
    {'cat': 'dialogue', 'text': 'Quatre, comte. Mais le quatrième ne le sait pas encore.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0173_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0173', 'turn': 2, 'speaker': 'B', 'context': 'fifth fiance'},
    {'cat': 'dialogue', 'text': 'Puis-je être le cinquième ? Je suis très patient.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0173_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0173', 'turn': 3, 'speaker': 'A', 'context': 'fifth fiance'},
    {'cat': 'dialogue', 'text': 'Pourquoi portez-vous toujours une cape, comte ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0174_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0174', 'turn': 1, 'speaker': 'A', 'context': 'cape'},
    {'cat': 'dialogue', 'text': "Pour les courants d'air. Et pour les sorties rapides.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0174_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0174', 'turn': 2, 'speaker': 'B', 'context': 'cape'},
    {'cat': 'dialogue', 'text': 'Comte, vous qui êtes riche, une petite avance ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0175_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0175', 'turn': 1, 'speaker': 'A', 'context': 'lend attention'},
    {'cat': 'dialogue', 'text': "Je ne prête jamais d'argent, Victor. Je prête autre chose.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0175_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0175', 'turn': 2, 'speaker': 'B', 'context': 'lend attention'},
    {'cat': 'dialogue', 'text': 'Quoi donc ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0175_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0175', 'turn': 3, 'speaker': 'A', 'context': 'lend attention'},
    {'cat': 'dialogue', 'text': 'Attention. Et elle se rembourse avec intérêts.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0175_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0175', 'turn': 4, 'speaker': 'B', 'context': 'lend attention'},
    {'cat': 'dialogue', 'text': 'Une veine bat sur votre tempe, Victor. Vous êtes nerveux ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0176_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0176', 'turn': 1, 'speaker': 'A', 'context': 'vein'},
    {'cat': 'dialogue', 'text': "C'est la roulette. J'ai perdu cent francs.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0176_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0176', 'turn': 2, 'speaker': 'B', 'context': 'vein'},
    {'cat': 'dialogue', 'text': "Ce n'est pas la roulette qui m'intéressait.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0176_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0176', 'turn': 3, 'speaker': 'A', 'context': 'vein'},
    {'cat': 'dialogue', 'text': 'Votre château a des fantômes, comte ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0177_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0177', 'turn': 1, 'speaker': 'A', 'context': 'ghosts'},
    {'cat': 'dialogue', 'text': 'Non. Les fantômes ont peur de nous.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0177_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0177', 'turn': 2, 'speaker': 'B', 'context': 'ghosts'},
    {'cat': 'dialogue', 'text': 'Vous jouez au baccara comme un homme qui a déjà tout perdu.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0178_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0178', 'turn': 1, 'speaker': 'A', 'context': 'despair'},
    {'cat': 'dialogue', 'text': "C'est mon style, comte. L'élégance du désespoir.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0178_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0178', 'turn': 2, 'speaker': 'B', 'context': 'despair'},
    {'cat': 'dialogue', 'text': "J'en ai connu d'autres. Ils reposent tous dans mon caveau. Je plaisante.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0178_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0178', 'turn': 3, 'speaker': 'A', 'context': 'despair'},
    {'cat': 'dialogue', 'text': 'Comte, où étiez-vous à onze heures dix ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0179_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0179', 'turn': 1, 'speaker': 'A', 'context': 'moon'},
    {'cat': 'dialogue', 'text': 'Dans le jardin, à chercher la lune.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0179_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0179', 'turn': 2, 'speaker': 'B', 'context': 'moon'},
    {'cat': 'dialogue', 'text': "Il n'y a pas de lune, ce soir.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0179_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0179', 'turn': 3, 'speaker': 'A', 'context': 'moon'},
    {'cat': 'dialogue', 'text': 'Justement. Elle se cache. Comme vous.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0179_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0179', 'turn': 4, 'speaker': 'B', 'context': 'moon'},
    {'cat': 'dialogue', 'text': 'Vous portez du noir, vous aimez la nuit, et vous ne mangez rien. Vous êtes de la famille ?', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0180_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0180', 'turn': 1, 'speaker': 'A', 'context': 'family'},
    {'cat': 'dialogue', 'text': 'Je mange. Mais jamais en public.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0180_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0180', 'turn': 2, 'speaker': 'B', 'context': 'family'},
    {'cat': 'dialogue', 'text': 'Ah ! Vous voyez !', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0180_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0180', 'turn': 3, 'speaker': 'A', 'context': 'family'},
    {'cat': 'dialogue', 'text': 'Il manque un couteau en argent au buffet, comte.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0181_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0181', 'turn': 1, 'speaker': 'A', 'context': 'silver knife'},
    {'cat': 'dialogue', 'text': "Un couteau en argent ? Je n'y touche jamais. Une allergie.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0181_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0181', 'turn': 2, 'speaker': 'B', 'context': 'silver knife'},
    {'cat': 'dialogue', 'text': "C'est bien ce qui m'intrigue.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0181_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0181', 'turn': 3, 'speaker': 'A', 'context': 'silver knife'},
    {'cat': 'dialogue', 'text': 'Votre justice est lente, monsieur Minuit.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0182_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0182', 'turn': 1, 'speaker': 'A', 'context': 'eternal justice'},
    {'cat': 'dialogue', 'text': 'La vôtre est éternelle, je suppose.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0182_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0182', 'turn': 2, 'speaker': 'B', 'context': 'eternal justice'},
    {'cat': 'dialogue', 'text': 'Touché.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0182_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0182', 'turn': 3, 'speaker': 'A', 'context': 'eternal justice'},
    {'cat': 'dialogue', 'text': "Dis donc, le comte, t'as jamais faim ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0183_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0183', 'turn': 1, 'speaker': 'A', 'context': 'hungry'},
    {'cat': 'dialogue', 'text': "J'ai toujours faim, mademoiselle. Je suis simplement difficile.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0183_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0183', 'turn': 2, 'speaker': 'B', 'context': 'hungry'},
    {'cat': 'dialogue', 'text': "Mademoiselle Odette, me ferez-vous l'honneur d'une valse ?", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0184_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0184', 'turn': 1, 'speaker': 'A', 'context': 'cold waltz'},
    {'cat': 'dialogue', 'text': "Avec plaisir, mais t'as les mains gelées, je te préviens.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0184_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0184', 'turn': 2, 'speaker': 'B', 'context': 'cold waltz'},
    {'cat': 'dialogue', 'text': 'Alors serrez-les fort. Elles se réchauffent vite.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0184_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0184', 'turn': 3, 'speaker': 'A', 'context': 'cold waltz'},
    {'cat': 'dialogue', 'text': "C'est vrai que tu te transformes en chauve-souris ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0185_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0185', 'turn': 1, 'speaker': 'A', 'context': 'bat'},
    {'cat': 'dialogue', 'text': 'Seulement pour éviter les fâcheux.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0185_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0185', 'turn': 2, 'speaker': 'B', 'context': 'bat'},
    {'cat': 'dialogue', 'text': 'Ah ben ce soir, tu vas voler beaucoup.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0185_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0185', 'turn': 3, 'speaker': 'A', 'context': 'bat'},
    {'cat': 'dialogue', 'text': "Votre voix porte jusqu'à la crypte, mademoiselle.", 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0186_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0186', 'turn': 1, 'speaker': 'A', 'context': 'crypt'},
    {'cat': 'dialogue', 'text': 'Il y a une crypte, ici ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0186_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0186', 'turn': 2, 'speaker': 'B', 'context': 'crypt'},
    {'cat': 'dialogue', 'text': 'Il y en a toujours une, quand on sait chercher.', 'voice': 'char_comte', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0186_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0186', 'turn': 3, 'speaker': 'A', 'context': 'crypt'},
    {'cat': 'dialogue', 'text': "Sandra, vous êtes la plus belle femme de l'île.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0187_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0187', 'turn': 1, 'speaker': 'A', 'context': 'archipelago'},
    {'cat': 'dialogue', 'text': 'Nous sommes sur une île minuscule, Victor.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0187_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0187', 'turn': 2, 'speaker': 'B', 'context': 'archipelago'},
    {'cat': 'dialogue', 'text': "Alors de tout l'archipel.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0187_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0187', 'turn': 3, 'speaker': 'A', 'context': 'archipelago'},
    {'cat': 'dialogue', 'text': 'Victor, savez-vous qui est le monsieur au masque bleu nuit ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0188_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0188', 'turn': 1, 'speaker': 'A', 'context': 'blue mask'},
    {'cat': 'dialogue', 'text': "Aucune idée. Il m'a donné le montant exact de mes dettes.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0188_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0188', 'turn': 2, 'speaker': 'B', 'context': 'blue mask'},
    {'cat': 'dialogue', 'text': 'Mon Dieu. Il est donc vraiment bien renseigné.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0188_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0188', 'turn': 3, 'speaker': 'A', 'context': 'blue mask'},
    {'cat': 'dialogue', 'text': "Si je gagne au baccara cette nuit, vous m'épousez ?", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0189_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0189', 'turn': 1, 'speaker': 'A', 'context': 'win'},
    {'cat': 'dialogue', 'text': "Si vous gagnez, je vous laisse m'offrir une coupe.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0189_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0189', 'turn': 2, 'speaker': 'B', 'context': 'win'},
    {'cat': 'dialogue', 'text': "C'est déjà un début.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0189_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0189', 'turn': 3, 'speaker': 'A', 'context': 'win'},
    {'cat': 'dialogue', 'text': 'Votre queue-de-pie est froissée, Victor.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0190_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0190', 'turn': 1, 'speaker': 'A', 'context': 'creased'},
    {'cat': 'dialogue', 'text': "J'ai dormi dedans. Mon hôtel m'a mis à la porte.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0190_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0190', 'turn': 2, 'speaker': 'B', 'context': 'creased'},
    {'cat': 'dialogue', 'text': 'Vous êtes impossible.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0190_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0190', 'turn': 3, 'speaker': 'A', 'context': 'creased'},
    {'cat': 'dialogue', 'text': "Je suis disponible. C'est presque pareil.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0190_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0190', 'turn': 4, 'speaker': 'B', 'context': 'creased'},
    {'cat': 'dialogue', 'text': 'Mademoiselle, vous avez quitté le salon à onze heures.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0191_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0191', 'turn': 1, 'speaker': 'A', 'context': 'powder nose'},
    {'cat': 'dialogue', 'text': 'Pour me repoudrer le nez.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0191_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0191', 'turn': 2, 'speaker': 'B', 'context': 'powder nose'},
    {'cat': 'dialogue', 'text': "Dans le bureau d'Ashcombe ?", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0191_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0191', 'turn': 3, 'speaker': 'A', 'context': 'powder nose'},
    {'cat': 'dialogue', 'text': 'La lumière y est meilleure.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0191_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0191', 'turn': 4, 'speaker': 'B', 'context': 'powder nose'},
    {'cat': 'dialogue', 'text': 'Vous dansez, monsieur Minuit ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0192_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0192', 'turn': 1, 'speaker': 'A', 'context': 'dance dark'},
    {'cat': 'dialogue', 'text': 'Seulement quand personne ne regarde.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0192_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0192', 'turn': 2, 'speaker': 'B', 'context': 'dance dark'},
    {'cat': 'dialogue', 'text': 'Alors éteignons les lumières.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0192_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0192', 'turn': 3, 'speaker': 'A', 'context': 'dance dark'},
    {'cat': 'dialogue', 'text': 'Vous connaissez les secrets de tout le monde, mademoiselle.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0193_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0193', 'turn': 1, 'speaker': 'A', 'context': 'team'},
    {'cat': 'dialogue', 'text': 'Et vous, vous les gardez. Nous ferions une belle équipe.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0193_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0193', 'turn': 2, 'speaker': 'B', 'context': 'team'},
    {'cat': 'dialogue', 'text': 'Ou un beau scandale.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0193_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0193', 'turn': 3, 'speaker': 'A', 'context': 'team'},
    {'cat': 'dialogue', 'text': 'On dit que vous êtes un ancien policier.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0194_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0194', 'turn': 1, 'speaker': 'A', 'context': 'policeman'},
    {'cat': 'dialogue', 'text': 'On dit beaucoup de choses.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0194_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0194', 'turn': 2, 'speaker': 'B', 'context': 'policeman'},
    {'cat': 'dialogue', 'text': "Et c'est vrai ?", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0194_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0194', 'turn': 3, 'speaker': 'A', 'context': 'policeman'},
    {'cat': 'dialogue', 'text': "Ce qui est vrai, c'est que je n'ai jamais rien dit.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0194_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0194', 'turn': 4, 'speaker': 'B', 'context': 'policeman'},
    {'cat': 'dialogue', 'text': 'Sandra, tu me prêtes ton rouge à lèvres ? Le mien a fondu.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0195_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0195', 'turn': 1, 'speaker': 'A', 'context': 'lipstick'},
    {'cat': 'dialogue', 'text': "Garde-le. Il te va mieux qu'à moi. Ne le répète pas.", 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0195_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0195', 'turn': 2, 'speaker': 'B', 'context': 'lipstick'},
    {'cat': 'dialogue', 'text': 'Odette, dis-moi franchement : le colonel est-il veuf ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0196_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0196', 'turn': 1, 'speaker': 'A', 'context': 'widower'},
    {'cat': 'dialogue', 'text': 'Marié, ma belle. Sa femme est au buffet depuis le début.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0196_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0196', 'turn': 2, 'speaker': 'B', 'context': 'widower'},
    {'cat': 'dialogue', 'text': 'Ah. Voilà qui change mes plans.', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0196_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0196', 'turn': 3, 'speaker': 'A', 'context': 'widower'},
    {'cat': 'dialogue', 'text': "Tu sais que Victor t'a demandée en mariage devant moi, l'an dernier ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0197_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0197', 'turn': 1, 'speaker': 'A', 'context': 'proposals'},
    {'cat': 'dialogue', 'text': 'Devant toi ? Et alors ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0197_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0197', 'turn': 2, 'speaker': 'B', 'context': 'proposals'},
    {'cat': 'dialogue', 'text': "Le lendemain, il me l'a demandé à moi.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0197_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0197', 'turn': 3, 'speaker': 'A', 'context': 'proposals'},
    {'cat': 'dialogue', 'text': 'Tu chantes quoi, à minuit ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0198_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0198', 'turn': 1, 'speaker': 'A', 'context': 'sad song'},
    {'cat': 'dialogue', 'text': 'Une chanson triste, sur une fille qui épouse un riche.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0198_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0198', 'turn': 2, 'speaker': 'B', 'context': 'sad song'},
    {'cat': 'dialogue', 'text': 'Et ça finit comment ?', 'voice': 'char_f_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0198_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0198', 'turn': 3, 'speaker': 'A', 'context': 'sad song'},
    {'cat': 'dialogue', 'text': 'Bien pour elle. Mal pour lui.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0198_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0198', 'turn': 4, 'speaker': 'B', 'context': 'sad song'},
    {'cat': 'dialogue', 'text': "Victor. Tony les Gants est sur l'île.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0199_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0199', 'turn': 1, 'speaker': 'A', 'context': 'tony'},
    {'cat': 'dialogue', 'text': 'Tony ? Ici ? Ce soir ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0199_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0199', 'turn': 2, 'speaker': 'B', 'context': 'tony'},
    {'cat': 'dialogue', 'text': 'Il vous cherche.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0199_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0199', 'turn': 3, 'speaker': 'A', 'context': 'tony'},
    {'cat': 'dialogue', 'text': 'Dites-lui que je suis mort. Avec élégance.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0199_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0199', 'turn': 4, 'speaker': 'B', 'context': 'tony'},
    {'cat': 'dialogue', 'text': 'Monsieur Minuit, vous êtes riche ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0200_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0200', 'turn': 1, 'speaker': 'A', 'context': 'rich'},
    {'cat': 'dialogue', 'text': 'Pas le moins du monde.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0200_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0200', 'turn': 2, 'speaker': 'B', 'context': 'rich'},
    {'cat': 'dialogue', 'text': 'Dommage. Nous aurions pu être amis.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0200_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0200', 'turn': 3, 'speaker': 'A', 'context': 'rich'},
    {'cat': 'dialogue', 'text': 'Vous avez des cartes dans la manche, Victor.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0201_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0201', 'turn': 1, 'speaker': 'A', 'context': 'king of hearts'},
    {'cat': 'dialogue', 'text': 'Ça se remarque tant que ça ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0201_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0201', 'turn': 2, 'speaker': 'B', 'context': 'king of hearts'},
    {'cat': 'dialogue', 'text': 'Le roi de cœur dépasse.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0201_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0201', 'turn': 3, 'speaker': 'A', 'context': 'king of hearts'},
    {'cat': 'dialogue', 'text': 'Si je vous dis qui a volé le collier, vous effacez mes dettes ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0202_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0202', 'turn': 1, 'speaker': 'A', 'context': 'deal'},
    {'cat': 'dialogue', 'text': 'Je ne suis pas banquier.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0202_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0202', 'turn': 2, 'speaker': 'B', 'context': 'deal'},
    {'cat': 'dialogue', 'text': "Personne n'est banquier ce soir. C'est bien le problème.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0202_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0202', 'turn': 3, 'speaker': 'A', 'context': 'deal'},
    {'cat': 'dialogue', 'text': 'Victor, tu me dois toujours cinquante francs.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0203_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0203', 'turn': 1, 'speaker': 'A', 'context': 'fifty francs'},
    {'cat': 'dialogue', 'text': 'Je vous les rends en baisers, Odette.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0203_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0203', 'turn': 2, 'speaker': 'B', 'context': 'fifty francs'},
    {'cat': 'dialogue', 'text': 'Pas de crédit chez moi, mon chou.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0203_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0203', 'turn': 3, 'speaker': 'A', 'context': 'fifty francs'},
    {'cat': 'dialogue', 'text': 'Chantez-moi quelque chose de gai, Odette.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0204_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0204', 'turn': 1, 'speaker': 'A', 'context': 'bailiffs'},
    {'cat': 'dialogue', 'text': 'Pour toi ? Une chanson sur les huissiers, alors.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0204_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0204', 'turn': 2, 'speaker': 'B', 'context': 'bailiffs'},
    {'cat': 'dialogue', 'text': "T'as vu la duchesse ? Elle te fixe depuis une heure.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0205_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0205', 'turn': 1, 'speaker': 'A', 'context': 'duchess'},
    {'cat': 'dialogue', 'text': 'La duchesse ? Elle est riche ?', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0205_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0205', 'turn': 2, 'speaker': 'B', 'context': 'duchess'},
    {'cat': 'dialogue', 'text': 'Riche et veuve.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0205_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0205', 'turn': 3, 'speaker': 'A', 'context': 'duchess'},
    {'cat': 'dialogue', 'text': "Excusez-moi, j'ai une valse urgente.", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'gossip', 'line_id': 'CD0205_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0205', 'turn': 4, 'speaker': 'B', 'context': 'duchess'},
    {'cat': 'dialogue', 'text': "Odette, si je devenais riche, vous m'épouseriez ?", 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0206_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0206', 'turn': 1, 'speaker': 'A', 'context': 'if rich'},
    {'cat': 'dialogue', 'text': "Si tu devenais riche, tu m'oublierais.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0206_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0206', 'turn': 2, 'speaker': 'B', 'context': 'if rich'},
    {'cat': 'dialogue', 'text': 'Jamais. Enfin, pas tout de suite.', 'voice': 'char_m_tailcoat', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0206_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0206', 'turn': 3, 'speaker': 'A', 'context': 'if rich'},
    {'cat': 'dialogue', 'text': "T'as l'air triste, monsieur Minuit. Tu veux une chanson ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0207_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0207', 'turn': 1, 'speaker': 'A', 'context': 'night song'},
    {'cat': 'dialogue', 'text': 'Chantez celle sur la nuit.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0207_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0207', 'turn': 2, 'speaker': 'B', 'context': 'night song'},
    {'cat': 'dialogue', 'text': 'Je les chante toutes la nuit, mon chou.', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0207_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0207', 'turn': 3, 'speaker': 'A', 'context': 'night song'},
    {'cat': 'dialogue', 'text': 'Mademoiselle, ne chantez pas trop près des fenêtres, ce soir.', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0208_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0208', 'turn': 1, 'speaker': 'A', 'context': 'windows'},
    {'cat': 'dialogue', 'text': 'Pourquoi ? Les chats vont se plaindre ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0208_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0208', 'turn': 2, 'speaker': 'B', 'context': 'windows'},
    {'cat': 'dialogue', 'text': "Quelqu'un surveille le jardin.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0208_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0208', 'turn': 3, 'speaker': 'A', 'context': 'windows'},
    {'cat': 'dialogue', 'text': "Le majordome cache une bouteille derrière l'horloge. Je l'ai vu.", 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0209_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0209', 'turn': 1, 'speaker': 'A', 'context': 'bottle clock'},
    {'cat': 'dialogue', 'text': 'Intéressant. Quelle marque ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0209_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0209', 'turn': 2, 'speaker': 'B', 'context': 'bottle clock'},
    {'cat': 'dialogue', 'text': "T'es pas censé t'intéresser au vol, plutôt ?", 'voice': 'char_odette', 'gender': 'f', 'reg': 'gossip', 'line_id': 'CD0209_3', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0209', 'turn': 3, 'speaker': 'A', 'context': 'bottle clock'},
    {'cat': 'dialogue', 'text': "Je m'intéresse à tout.", 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0209_4', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0209', 'turn': 4, 'speaker': 'B', 'context': 'bottle clock'},
    {'cat': 'dialogue', 'text': 'Vous chantez « Minuit, chrétiens » ?', 'voice': 'char_minuit', 'gender': 'm', 'reg': 'neutral', 'line_id': 'CD0210_1', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0210', 'turn': 1, 'speaker': 'A', 'context': 'christmas'},
    {'cat': 'dialogue', 'text': 'Seulement à Noël, mon chou. Et toi, tu souris seulement à Pâques ?', 'voice': 'char_odette', 'gender': 'f', 'reg': 'neutral', 'line_id': 'CD0210_2', 'whispered': False, 'nonverbal': False, 'gun': False, 'dialogue_id': 'CD0210', 'turn': 2, 'speaker': 'B', 'context': 'christmas'},
]
